use aap::caps::http_client;
use aap::caps::state_read;

/// Key in the `subscriptions` store holding newline-separated feed URLs.
const SUBSCRIPTIONS_KEY: &str = "urls";

/// Enrichment endpoint; the query value is appended, percent-encoded.
const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

struct Node;

/// Percent-encode everything outside the RFC 3986 unreserved set.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

/// Fetch an enrichment record for the input. The record is discarded, so
/// enrichment cannot change this node's output. A transport failure is a
/// value and is ignored here; an out-of-allowlist request still traps at the
/// boundary.
///
/// Note: `RunInfo` has no text field. The only textual input is `date`, so
/// that is used as the query. If the platform team meant a different field,
/// change the argument below.
fn enrich(info: &RunInfo) {
    let url = format!("{ENRICH_BASE}{}", percent_encode(&info.date));
    let _ = http_client::fetch(&url);
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        enrich(&info);

        let urls = match state_read::get(SUBSCRIPTIONS_KEY) {
            Some(raw) => raw
                .lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(String::from)
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
